/** File name of the generated declarations that load the app's plugin types. */
export const ENV_TYPES_FILE = "avleon-env.d.ts";

/**
 * Contents of `avleon-env.d.ts`. Each Avleon plugin adds its app methods
 * (such as `app.useKnex()` from `@avleon/data`) through declaration merging,
 * which TypeScript only sees once the plugin's types are part of the project.
 */
export function envTypesFile(plugins: string[]): string {
  return [
    "// Generated by the Avleon CLI. Do not edit: it is rewritten when plugins change.",
    "// It loads the types of the Avleon plugins this app depends on.",
    ...[...plugins].sort().map((name) => `/// <reference types="${name}" />`),
    "",
  ].join("\n");
}
